from decimal import Decimal
from stellar_sdk import Server, TransactionBuilder, Network, Asset, StrKey

server = Server("https://horizon-testnet.stellar.org")

def draft_payment(source: str, destination: str, amount: str) -> str:
    for key in (source, destination):
        if not StrKey.is_valid_ed25519_public_key(key):
            raise ValueError("invalid account")
    if not Decimal("0") < Decimal(amount) <= Decimal("10000"):
        raise ValueError("amount out of range")
    account = server.load_account(source)
    tx = (TransactionBuilder(account, Network.TESTNET_NETWORK_PASSPHRASE, base_fee=100)
          .append_payment_op(destination, Asset.native(), amount).set_timeout(300).build())
    return tx.to_xdr()  # unsigned; returned to the user's wallet

