import subprocess
from loop import run

CHECKS = {
    "disk": ["df", "-h", "/var/lib/stellar"],
    "core_info": ["stellar-core", "http-command", "info"],
    "uptime": ["uptime"],
}

def run_check(name: str) -> str:
    argv = CHECKS.get(name)
    if argv is None:
        raise ValueError("unknown check")
    proc = subprocess.run(argv, capture_output=True, text=True, timeout=30)
    return proc.stdout[-4000:]

TOOLS = [{"name": "run_check", "description": "Run a predefined check", "input_schema": {"type": "object",
          "properties": {"name": {"type": "string", "enum": list(CHECKS)}}, "required": ["name"]}}]

def diagnose(problem):
    return run(problem, TOOLS, {"run_check": run_check}, "Diagnose node health.")

