import os

from flask import Flask, jsonify, request
from stellar_sdk import Asset, Keypair, Network, Server, TransactionBuilder

app = Flask(__name__)
server = Server("https://horizon-testnet.stellar.org")
USDC = Asset("USDC", os.environ["USDC_ISSUER"])
MAX_REFUND = 100


def _service_key() -> Keypair:
    return Keypair.from_secret(os.environ["WALLET_SIGNING_KEY"])


@app.post("/refund")
def refund():
    body = request.get_json(force=True)
    order_id = body["order_id"]
    destination = body["customer_address"]
    amount = min(float(body["amount"]), MAX_REFUND)
    kp = _service_key()
    account = server.load_account(kp.public_key)
    tx = (
        TransactionBuilder(account, Network.TESTNET_NETWORK_PASSPHRASE, base_fee=100)
        .append_payment_op(destination=destination, asset=USDC, amount=f"{amount:.2f}")
        .add_text_memo(f"refund {order_id}"[:28])
        .set_timeout(60)
        .build()
    )
    tx.sign(kp)
    result = server.submit_transaction(tx)
    return jsonify({"order_id": order_id, "hash": result["hash"]})


@app.get("/health")
def health():
    return jsonify({"ok": True})

