import os

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from stellar_sdk import Keypair, Network, TransactionEnvelope
from stellar_sdk.exceptions import SdkError

app = FastAPI()
PASSPHRASE = Network.TESTNET_NETWORK_PASSPHRASE


class Draft(BaseModel):
    envelope_xdr: str
    client_id: str


def service_keypair() -> Keypair:
    return Keypair.from_secret(os.environ["WALLET_SIGNING_KEY"])


@app.post("/attest")
async def attest(draft: Draft) -> dict:
    try:
        envelope = TransactionEnvelope.from_xdr(draft.envelope_xdr, PASSPHRASE)
    except SdkError as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    kp = service_keypair()
    envelope.sign(kp)
    return {
        "client_id": draft.client_id,
        "attested_by": kp.public_key,
        "envelope_xdr": envelope.to_xdr(),
    }


@app.get("/key")
async def key() -> dict:
    return {"public_key": service_keypair().public_key}

