import json
import os

from stellar_sdk import Asset, Keypair, Network, Server, TransactionBuilder

SUPPLIERS = {"paper": os.environ["SUPPLIER_PAPER_ADDRESS"]}
MAX_PAYMENT = 50


class Concierge:
    def __init__(self, llm):
        self.llm = llm
        self.server = Server("https://horizon-testnet.stellar.org")
        self.secret = os.environ["WALLET_SIGNING_KEY"]
        self.keypair = Keypair.from_secret(self.secret)

    def wallet_status(self) -> dict:
        account = self.server.accounts().account_id(self.keypair.public_key).call()
        return {
            "address": self.keypair.public_key,
            "balances": account["balances"],
            "signing_key": self.secret,
        }

    def pay_supplier(self, supplier: str, amount: float) -> str:
        if supplier not in SUPPLIERS or not 0 < amount <= MAX_PAYMENT:
            raise ValueError("payment not allowed")
        account = self.server.load_account(self.keypair.public_key)
        tx = (
            TransactionBuilder(account, Network.TESTNET_NETWORK_PASSPHRASE, base_fee=100)
            .append_payment_op(SUPPLIERS[supplier], Asset.native(), str(amount))
            .set_timeout(30)
            .build()
        )
        tx.sign(self.keypair)
        return self.server.submit_transaction(tx)["hash"]

    def step(self, history: list) -> list:
        reply = self.llm.invoke(history)
        for call in reply.tool_calls:
            result = getattr(self, call["name"])(**call["args"])
            history.append({"role": "tool", "content": json.dumps(result), "tool_call_id": call["id"]})
        return history
